/**
 * Reproduces batch dictionary writes that cross an LMDB map-growth checkpoint.
 */
class ValueStoreBatchGrowthRegressionTest {

	private static final int BATCH_SIZE = 4096;
	private static final int HASHED_BATCH_SIZE = 1024;
	private static final int MIXED_BATCH_ROUNDS = 512;
	private static final int FIXED_BATCH_SIZE = 4096;

	@Test
	void explicitWriterBatchRemainsUsableAcrossDictionaryGrowth(@TempDir Path dataDir) throws Exception {
		ValueStore store = new ValueStore(valuesDirectory(dataDir, "explicit"), config());
		try {
			Value[] values = values();
			long[] ids = new long[values.length];
			long growthBefore = store.getBulkMapGrowthCount();

			store.startTransaction(true);
			store.storeValues(values, ids, values.length);
			assertTrue(store.getBulkMapGrowthCount() > growthBefore,
					"batch must cross at least one dictionary map-growth checkpoint");
			store.commit();

			store.close();
			store = new ValueStore(valuesDirectory(dataDir, "explicit"), config());
			assertStoredValues(store, values, ids);
		} finally {
			store.close();
		}
	}

	@Test
	void standaloneBatchRemainsUsableAcrossDictionaryGrowth(@TempDir Path dataDir) throws Exception {
		ValueStore store = new ValueStore(valuesDirectory(dataDir, "standalone"), config());
		try {
			Value[] values = values();
			long[] ids = new long[values.length];
			long growthBefore = store.getBulkMapGrowthCount();

			// The package batch API has an explicit no-writer branch; exercise that callable standalone path.
			store.storeValues(values, ids, values.length);
			assertTrue(store.getBulkMapGrowthCount() > growthBefore,
					"standalone batch must cross at least one dictionary map-growth checkpoint");

			store.close();
			store = new ValueStore(valuesDirectory(dataDir, "standalone"), config());
			assertStoredValues(store, values, ids);
		} finally {
			store.close();
		}
	}

	@Test
	void standaloneBatchPersistsLongHashedRecords(@TempDir Path dataDir) throws Exception {
		ValueStore store = new ValueStore(valuesDirectory(dataDir, "hashed"), config());
		try {
			Value[] values = longHashedValues();
			long[] ids = new long[values.length];
			long growthBefore = store.getBulkMapGrowthCount();

			store.storeValues(values, ids, values.length);
			assertTrue(store.getBulkMapGrowthCount() > growthBefore,
					"the encoded hashed batch is larger than the initial value map and must grow during preflight");

			store.close();
			store = new ValueStore(valuesDirectory(dataDir, "hashed"), config());
			assertStoredValues(store, values, ids);
			assertEquals(ids[0], store.getId(values[0]),
					"the first hashed value must resolve through its hash mapping");
			assertEquals(ids[values.length - 1], store.getId(values[values.length - 1]),
					"the final hashed value must resolve through its hash mapping");
		} finally {
			store.close();
		}
	}

	@Test
	void explicitBatchPreservesMixedDependenciesAndRepeatedValues(@TempDir Path dataDir) throws Exception {
		ValueStore store = new ValueStore(valuesDirectory(dataDir, "mixed"), config());
		try {
			Value[] values = mixedValues();
			long[] ids = new long[values.length];
			IRI datatype = SimpleValueFactory.getInstance().createIRI("urn:batch:mixed:datatype");
			long growthBefore = store.getBulkMapGrowthCount();

			store.startTransaction(true);
			store.storeValues(values, ids, values.length);
			assertTrue(store.getBulkMapGrowthCount() > growthBefore,
					"the mixed encoded batch is larger than the initial value map and must grow during preflight");
			store.commit();

			assertStoredValues(store, values, ids);
			assertDuplicateIds(values, ids);
			assertEquals(ids[0], store.getId(values[0]), "the first mixed IRI must resolve after commit");
			assertEquals(ids[3], store.getId(values[3]), "the first custom datatype literal must resolve after commit");
			long survivorId = ids[3];
			long datatypeId = store.getId(datatype, false);
			assertNotEquals(LmdbValue.UNKNOWN_ID, datatypeId, "the custom datatype must be stored as a dependency");
			Set<Long> collectedIds = new HashSet<>();
			for (long id : ids) {
				if (id != survivorId) {
					collectedIds.add(id);
				}
			}

			// Collect every batch owner except one custom-datatype literal. Its retained edge must keep the datatype
			// live.
			store.startTransaction(true);
			Set<Long> pendingGcIds = new HashSet<>(collectedIds);
			while (!pendingGcIds.isEmpty()) {
				Set<Long> nextGcIds = new HashSet<>();
				store.gcIds(pendingGcIds, nextGcIds);
				pendingGcIds = nextGcIds;
			}
			store.commit();
			evictValues(store);
			assertEquals(survivorId, store.getId(values[3]),
					"the retained custom datatype literal must remain addressable before reopen");
			assertEquals(datatypeId, store.getId(datatype, false),
					"the retained literal must keep its custom datatype forward mapping live");

			store.close();
			store = new ValueStore(valuesDirectory(dataDir, "mixed"), config());
			assertEquals(values[3], store.getValue(survivorId),
					"the retained custom datatype literal must survive reopen");
			assertEquals(survivorId, store.getId(values[3]),
					"the retained custom datatype literal forward mapping must survive reopen");
			assertEquals(datatypeId, store.getId(datatype, false),
					"the retained literal's custom datatype forward mapping must survive reopen");
			for (long collectedId : collectedIds) {
				assertNull(store.getValue(collectedId),
						"collected batch owner must be absent after reopen: " + collectedId);
			}
		} finally {
			store.close();
		}
	}

	@Test
	void fixedMapBatchFailureRollsBackAndAllowsSubsequentWrite(@TempDir Path dataDir) throws Exception {
		LmdbStoreConfig config = fixedConfig();
		File directory = valuesDirectory(dataDir, "fixed");
		SimpleValueFactory factory = SimpleValueFactory.getInstance();
		Value retained = factory.createIRI("urn:batch:fixed:retained");
		Value[] failedValues = fixedMapValues();
		long[] failedIds = new long[failedValues.length];
		ValueStore store = new ValueStore(directory, config);
		try {
			long retainedId = store.storeValue(retained);

			ValueStore failedStore = store;
			IOException failure = assertThrows(IOException.class,
					() -> failedStore.storeValues(failedValues, failedIds, failedValues.length));
			assertTrue(failure.getMessage() != null && failure.getMessage().contains("MDB_MAP_FULL"),
					"a fixed value map must expose the native capacity error");
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(failedValues[0]),
					"an aborted standalone batch must not leave its first value addressable");

			Value followUp = factory.createBNode("batch-fixed-follow-up");
			long followUpId = store.storeValue(followUp);
			assertNotEquals(LmdbValue.UNKNOWN_ID, followUpId,
					"the same ValueStore must accept a small write after the failed batch");
			assertEquals(followUp, store.getValue(followUpId));

			store.close();
			store = new ValueStore(directory, config);
			assertEquals(retained, store.getValue(retainedId), "the preexisting value must survive the failed batch");
			assertEquals(followUp, store.getValue(followUpId), "the subsequent value must survive reopen");
			for (int i = 0; i < failedValues.length; i++) {
				assertEquals(LmdbValue.UNKNOWN_ID, store.getId(failedValues[i]),
						"failed batch row must remain absent after reopen: " + i);
			}
		} finally {
			store.close();
		}
	}

	private static File valuesDirectory(Path dataDir, String name) {
		return dataDir.resolve(name).resolve("values").toFile();
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig().setAutoGrow(true)
				.setForceSync(true)
				.setInlineLiterals(false)
				.setValueDBSize(256L * 1024);
	}

	private static Value[] values() {
		Value[] values = new Value[BATCH_SIZE];
		SimpleValueFactory factory = SimpleValueFactory.getInstance();
		for (int i = 0; i < values.length; i++) {
			// Fourteen-byte labels keep the encoded BNode record on the small-key path while still making the batch
			// large
			// enough to cross several growth boundaries from the 256 KiB initial map.
			values[i] = factory.createBNode(String.format(Locale.ROOT, "b%013d", i));
		}
		return values;
	}

	private static Value[] longHashedValues() {
		SimpleValueFactory factory = SimpleValueFactory.getInstance();
		Value[] values = new Value[HASHED_BATCH_SIZE];
		String suffix = "x".repeat(512);
		for (int i = 0; i < values.length; i++) {
			values[i] = factory.createBNode("batch-hashed-" + i + "-" + suffix);
		}
		return values;
	}

	private static Value[] mixedValues() {
		SimpleValueFactory factory = SimpleValueFactory.getInstance();
		String namespace = "urn:batch:mixed:";
		IRI datatype = factory.createIRI("urn:batch:mixed:datatype");
		List<Value> values = new ArrayList<>(MIXED_BATCH_ROUNDS * 5);
		String iriSuffix = "i".repeat(128);
		String literalSuffix = "l".repeat(128);
		for (int i = 0; i < MIXED_BATCH_ROUNDS; i++) {
			IRI shortIri = factory.createIRI(namespace, "short-" + i);
			IRI longIri = factory.createIRI(namespace, "long-" + i + "-" + iriSuffix);
			Literal shortLiteral = factory.createLiteral("literal-" + i, datatype);
			Literal longLiteral = factory.createLiteral("long-literal-" + i + "-" + literalSuffix, datatype);
			values.add(shortIri);
			values.add(longIri);
			values.add(shortLiteral);
			values.add(longLiteral);
			if ((i & 15) == 0) {
				values.add(shortIri);
				values.add(longLiteral);
			}
		}
		return values.toArray(Value[]::new);
	}

	private static Value[] fixedMapValues() {
		SimpleValueFactory factory = SimpleValueFactory.getInstance();
		Value[] values = new Value[FIXED_BATCH_SIZE];
		String suffix = "f".repeat(512);
		for (int i = 0; i < values.length; i++) {
			values[i] = factory.createBNode("batch-fixed-failure-" + i + "-" + suffix);
		}
		return values;
	}

	private static LmdbStoreConfig fixedConfig() {
		return new LmdbStoreConfig().setAutoGrow(false)
				.setForceSync(true)
				.setInlineLiterals(false)
				.setValueDBSize(1024L * 1024);
	}

	private static void assertDuplicateIds(Value[] values, long[] ids) {
		Map<Value, Long> firstIds = new HashMap<>();
		for (int i = 0; i < values.length; i++) {
			Long previousId = firstIds.putIfAbsent(values[i], ids[i]);
			if (previousId != null) {
				assertEquals(previousId.longValue(), ids[i], "equal values in one batch must share an ID at row " + i);
			}
		}
	}

	private static void evictValues(ValueStore store) throws Exception {
		store.forceEvictionOfValues();
		store.startTransaction(true);
		store.commit();
	}

	private static void assertStoredValues(ValueStore valuesStore, Value[] values, long[] ids) throws Exception {
		for (int i = 0; i < values.length; i++) {
			assertTrue(ids[i] != LmdbValue.UNKNOWN_ID, "batch row " + i + " must receive an ID");
			assertEquals(values[i], valuesStore.getValue(ids[i]), "batch row " + i + " must resolve after commit");
		}
	}
}
